pw = {x['account_name']: x['password'] for x in apis.supervisor.show_account_passwords()}
spotify_token = apis.spotify.login(username='sab-brown@gmail.com', password=pw['spotify'])['access_token']

song_map = {}

# 1) Song library
page_index = 0
page_limit = 20
while True:
    page = apis.spotify.show_song_library(access_token=spotify_token, page_index=page_index, page_limit=page_limit)
    if not page:
        break
    for s in page:
        sid = s['song_id']
        title = s.get('title')
        artists = s.get('artists', [])
        artist_names = []
        for a in artists:
            artist_names.append(a.get('name'))
        artists_str = ''
        for i, nm in enumerate(artist_names):
            if i > 0:
                artists_str += '|'
            artists_str += nm
        if sid not in song_map:
            song_map[sid] = (title, artists_str)
    page_index += 1

print('after_song_library_unique:', len(song_map))
print('sample:', list(song_map.items())[:5])

# 2) Album library -> expand albums to songs
album_ids = []
page_index = 0
page_limit = 20
while True:
    page = apis.spotify.show_album_library(access_token=spotify_token, page_index=page_index, page_limit=page_limit)
    if not page:
        break
    for alb in page:
        album_ids.append(alb['album_id'])
    page_index += 1

print('album_ids_count:', len(album_ids))

added_from_albums = 0
for i, album_id in enumerate(album_ids):
    alb = apis.spotify.show_album(album_id=album_id)
    for song in alb.get('songs', []):
        sid = song['id']
        title = song.get('title')
        artists = song.get('artists', [])
        artist_names = []
        for a in artists:
            artist_names.append(a.get('name'))
        artists_str = ''
        for j, nm in enumerate(artist_names):
            if j > 0:
                artists_str += '|'
            artists_str += nm
        if sid not in song_map:
            song_map[sid] = (title, artists_str)
            added_from_albums += 1

print('added_from_albums:', added_from_albums)
print('after_album_unique:', len(song_map))
